import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
public class Main { public static void main(String[] args) throws IOException { try (FileWriter writer = new FileWriter("message.txt")) { writer.write("Hello Java"); } System.out.println(Files.readString(Path.of("message.txt"))); } }

import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
public class Main { public static void main(String[] args) throws IOException { try (FileWriter writer = new FileWriter("log.txt")) { writer.write("Start"); } try (FileWriter writer = new FileWriter("log.txt", true)) { writer.write("-End"); } System.out.println(Files.readString(Path.of("log.txt"))); } }

import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
public class Main { public static void main(String[] args) throws IOException { try (FileWriter writer = new FileWriter("lines.txt")) { writer.write("First\nSecond"); } System.out.println(Files.readString(Path.of("lines.txt")).lines().count()); } }

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
public class Main { public static void main(String[] args) throws IOException { Path path = Path.of("utf8.txt"); try (var writer = Files.newBufferedWriter(path, StandardCharsets.UTF_8)) { writer.write("CodeSaathi"); } System.out.println(Files.readString(path, StandardCharsets.UTF_8)); } }

